\begin{definition}\label{def:smooth_dom}
\lean{smoothDom}
\leanok
    Let $k\in \mathbb{N}$ be an integer, $\mathbb{F}$ be a finite field and $\mathcal{L}\subset \mathbb{F}$ be a subset of $\mathbb{F}$. Then 
    \[
    \mathcal{L}^k := \{x^k \text{ s.t. } x \in \mathcal{L}\}
    \]   
\end{definition}

n1366.content:
\begin{definition}[Reed-Solomon Code]\label{def:rscode}
\lean{ReedSolomonCode}
\leanok
\uses{def:smooth_dom}
    The \emph{Reed-Solomon code} over finite field $\mathbb{F}$, evaluation domain $\mathcal{L}\subseteq\mathbb{F}$ and degree $d\in\mathbb{N}$ is the set of evaluations (over $\mathcal{L}$) of univariate polynomials (over $\mathbb{F}$) of degree less than $d$:
    \[
        \mathrm{RS}[\mathbb{F},\mathcal{L},d]:=\; \bigl\{\, f : \mathcal{L}\to \mathbb{F}\;\big|\; \exists \,\hat{f} \,\in \mathbb{F}^{<d}[X]\text{ such that } \forall x \in \mathcal{L},\; f(x) = \hat{f}(x)\bigr\}.
    \]

    The rate of $\mathrm{RS}[\mathbb{F},\mathcal{L},d]$ is $\rho:= \frac{d}{\lvert \mathcal{L}\rvert}$.

    Given a code $\mathcal{C}:= \mathrm{RS}[\mathbb{F},\mathcal{L},d]$ and a function $f : \mathcal{L}\to \mathbb{F}$, we sometimes use $\hat{f} \in \mathbb{F}^{<d}[X]$ to denote a nearest polynomial to $f$ on $\mathcal{L}$ (breaking ties arbitrarily).
\end{definition}

n1367.content:
\begin{remark}
Note that the evaluation domain $\mathcal{L}\subseteq\mathbb{F}$ is a non-empty set.
\end{remark}

n1369.content:
\begin{theorem}[Johnson bound]\label{thm:johnson_bnd}
    \lean{johnson_bound}
    \leanok
    \uses{def:rscode,def:smooth_dom,def:list_decodable}
    \uses{def:rscode,def:list_decodable}
    The Reed-Solomon code $\mathrm{RS}[\mathbb{F},\mathcal{L},d]$ is $(1-\sqrt{\rho}-\eta,\frac{1}{2\eta\rho})$-list-decodable for every $\eta\in(0,1-\sqrt{\rho})$, where $\rho:=\frac{d}{|\mathcal{L}|}$ is the rate of the code.
    \end{theorem}

