\begin{definition}\label{def:quotient}
\lean{quotient}
\leanok
%\uses{}
    Let $f:\mathcal{L}\to\mathbb{F}$ be a function, $S\subseteq\mathbb{F}$ be a set, and $\mathsf{Ans},\mathsf{Fill}: S\rightarrow\mathbb{F}$ be functions. Let $\hat{\mathsf{Ans}}\in\mathbb{F}^{<|S|}[X]$ be the (unique) polynomial with $\hat{\mathsf{Ans}}(x)=\mathsf{Ans}(x)$ for every $x\in S$, and let $\hat{V}_S\in\mathbb{F}^{<|S|+1}[X]$ be the unique non-zero polynomial with $\hat{V}_S(x)=0$ for every $x\in S$.
    The \emph{quotient function} $\mathsf{Quotient}\bigl(f,S,\mathsf{Ans},\mathsf{Fill}\bigr): \mathcal{L}\to\mathbb{F}$
    is defined as follows:
\[
\forall x \in \mathcal{L},\quad
\mathsf{Quotient}\bigl(f,S,\mathsf{Ans},\mathsf{Fill}\bigr)(x)
:=
\begin{cases}
\mathsf{Fill}(x)
& \text{if } x \in S \\[6pt]
\dfrac{f(x) - \hat{\mathsf{Ans}}(x)}{\hat{V}_S(x)}
& \text{otherwise}
\end{cases}
\]
\end{definition}

n1372.content:
\begin{definition}\label{def:poly_quotient}
\lean{polyQuotient}
\leanok
\uses{}
    Let $\hat{f}\in\mathbb{F}^{<d}[X]$ be a polynomial and $S\subseteq\mathbb{F}$ be a set, let $\hat{V}_S\in\mathbb{F}^{<|S|+1}[X]$ be the unique non-zero polynomial with $\hat{V}_S(x)=0$ for every $x\in S$. The \emph{polynomial quotient} $\mathsf{PolyQuotient}(\hat{f},S)\in\mathbb{F}^{<d-|S|}[X]$ is defined as follows:
    \[
            \mathsf{PolyQuotient}(\hat{f},S)(X):=\frac{\hat{f}(X)-\hat{\mathsf{Ans}}(X)}{\hat{V}_S(X)}
    \]

\end{definition}

