\begin{lemma}\label{lemma:quotienting}
\lean{quotienting}
\leanok
\uses{def:quotient,def:rscode,def:list_decodable}
    Let $f:\mathcal{L}\rightarrow\mathbb{F}$ be a function, $d\in\mathbb{N}$ be the degree parameter, $\delta\in(0,1)$
    be a distance parameter, $S\subseteq\mathbb{F}$ be a set with $|S|<d$, and $\mathsf{Ans},\mathsf{Fill}:S\rightarrow\mathbb{F}$ are functions. Suppose that for every $u\in\mathsf{List}(f,d,\delta)$ there exists $x\in S$ with $\hat{u}(x)\neq\mathsf{Ans}(x)$. Then 
    \[
            \Delta(\mathsf{Quotient}(f,S,\mathsf{Ans},\mathsf{Fill}),\mathrm{RS}[\mathbb{F},\mathcal{L},d-|S|])+\frac{|T|}{|\mathcal{L}|}>\delta,
    \]
    where $T:=\{x\in\mathcal{L}\cap S: \hat{\mathsf{Ans}}(x)\neq f(x)\}$.
\end{lemma}

n1374.content:
\begin{lemma}\label{lemma:out_of_domain_smpl}
\lean{out_of_dom_smpl_1, out_of_dom_smpl_2}
\leanok
\uses{def:rscode,def:list_decodable}
    Let $f:\mathcal{L}\rightarrow\mathbb{F}$ be a function, $d\in\mathbb{N}$ be a degree parameter, $s\in\mathbb{N}$ be a repetition parameter, and $\delta\in[0,1]$ be a distance parameter. If $\mathrm{RS}[\mathbb{F},\mathcal{L},d]$ be $(d,l)$-list decodable then
    \begin{align*}
    \Pr_{r_1,\ldots,r_s\gets\mathbb{F}\setminus\mathcal{L}}[\exists\text{ distinct }u,u'\in\mathsf{List}(f,d,\delta):\forall i\in[s],\hat{u}(r_i)=\hat{u}'(r_i)] & \leq \binom{l}{2}\cdot{\Big(\frac{d-1}{|\mathbb{F}|-|\mathcal{L}|}\Big)}^s \\
    & \leq \Big(\frac{l^2}{2}\Big)\cdot{\Big(\frac{d}{|\mathbb{F}|-|\mathcal{L}|}\Big)}^s
    \end{align*}
\end{lemma}

