\begin{fact}\label{fact:poly_folding} %todo- add citation BS08
\lean{exists_unique_bivariate,degree_bound_bivariate}
\leanok
Given a polynomial $\hat{q}\in\mathbb{F}[X]$:
\begin{itemize}
    \item For every univariate polynomial $\hat{f}\in\mathbb{F}[X]$, there exists a unique bivariate polynomial $\hat{Q}\in\mathbb{F}[X,Y]$ with $\mathsf{deg}_X(\hat{Q}):=\lfloor{\mathsf{deg}(\hat{f})}/{\mathsf{deg}(\hat{q})}\rfloor$ and $\mathsf{deg}_Y(\hat{Q})<\mathsf{deg}(\hat{q})$ such that $\hat{f}(Z)=\hat{Q}(\hat{q}(Z),Z)$. Moreover $\hat{Q}$ can be computed efficiently given $\hat{f}$ and $\hat{q}$. Observe that if $\mathsf{deg}(\hat{f})<t\cdot\mathsf{deg}(\hat{q})$ then $\mathsf{deg}(\hat{Q})<t$.
    \item For every $\hat{Q}[X,Y]$ with $\mathsf{deg}_X(\hat{Q})<t$ and $\mathsf{deg}_Y(\hat{Q})<\mathsf{deg}(\hat{q})$, the polynomial $\hat{f}(Z)=\hat{Q}(\hat{q}(Z),Z)$ has degree $\mathsf{deg}(\hat{f})<t\cdot\mathsf{deg}(\hat{q})$.
\end{itemize}
\end{fact}

