\begin{definition}\label{def:poly_folding}
\lean{polyFold}
\leanok
\uses{fact:poly_folding}
    Given a polynomial $\hat{f}\in\mathbb{F}^{<d}[X]$, a folding parameter $k\in\mathbb{N}$ and $r\in\mathbb{F}$, we define a polynomial $\mathsf{PolyFold}(\hat{f},k,r)\in\mathbb{F}^{d/k}[X]$ as follows. Let $\hat{Q}[X,Y]$ be the bivariate polynomial derived from $\hat{f}$ using Fact~\ref{fact:poly_folding} with $\hat{q}(X):=X^k$. Then $\mathsf{PolyFold}(\hat{f},k,r)(X):=\hat{Q}(X,r)$.
\end{definition}

