\begin{definition}\label{def:fn_folding}
\lean{fold}
\leanok
Let $f:\mathcal{L}\rightarrow\mathbb{F}$ be a function, $k\in\mathbb{N}$ a folding parameter and $\alpha\in\mathbb{F}$. For every $x\in{\mathcal{L}}^k$, let $\hat{p}_x\in\mathbb{F}^{<k}[X]$ be the polynomial where $\hat{p}_x(y)=f(y)$ for every $y\in{\mathcal{L}}$ such that $y^k=x$. We define $\mathsf{Fold}(f,k,\alpha):\mathcal{L}\rightarrow\mathbb{F}$ as follows.
\[
    \mathsf{Fold}(f,k,\alpha):=\hat{p}_x(\alpha).
\]
In order to compute $\mathsf{Fold}(f,k,\alpha)(x)$ it suffices to interpolate the $k$ values $\{f(y):y\in\mathcal{L}\text{ s.t. }y^k=x\}$ into the polynomial $\hat{p}_x$ and evaluate this polynomial at $\alpha$.
\end{definition}

