\begin{lemma}\label{lemma:folding}
\lean{folding}
\leanok
\uses{def:rscode,def:fn_folding}
    For every function $f:\mathcal{L}\rightarrow\mathbb{F}$, degree parameter $d\in\mathbb{N}$, folding parameter $k\in\mathbb{N}$, distance parameter $\delta\in(0,\min\{{\Delta(\mathsf{Fold}[f,k,r^{\mathsf{fold}}],\mathrm{RS}[\mathbb{F},{\mathcal{L}}^k, d/k]),1-{\mathsf{B}}^*(\rho)}\})$, letting $\rho:=\frac{d}{|\mathcal{L}|}$,
    \[
        \Pr_{r^{\mathsf{fold}}\gets\mathbb{F}}[\Delta(\mathsf{Fold}[f,k,r^{\mathsf{fold}}],\mathrm{RS}[\mathbb{F},{\mathcal{L}}^k, d/k])<\delta]>\mathsf{err}^*(d/k,\rho,\delta,k).
    \]
    Above, ${\mathsf{B}}^*$ and ${\mathsf{err}}^*$ are the proximity bound and error (respectively) described in Section~\ref{sec:proximity_gap}.
\end{lemma}

