\begin{fact}\label{fact:geometric_sum}
\lean{geometric_sum_units}
\leanok
    Let $\mathbb{F}$ be a field, $r\in\mathbb{F}$ be a field element, $a\in\mathbb{N}$ be a natural number. Then
    \[
        \sum_{i=0}^{a}r^i:=
        \begin{cases}
        \Big(\frac{1-r^{a+1}}{1-r}\Big) & r\neq 1 \\
        a+1 & r=1
        \end{cases}
    \]
\end{fact}

