\begin{definition}\label{def:combine}
\lean{combineInterm,combineFinal}
\leanok
%\uses{}
    Given target degree $d^*\in\mathbb{N}$, shifting parameter $r\in\mathbb{F}$, functions $f_1,\ldots,f_m:\mathcal{L}\rightarrow\mathbb{F}$, and degrees $0\leq d_1,\ldots,d_m\leq {d}^*$, we define $\mathsf{Combine}(d^*,r,(f_1,d_1),\ldots,(f_m,d_m)):\mathcal{L}\rightarrow\mathbb{F}$ as follows:
    \begin{align*}
        \mathsf{Combine}({d}^*,r,(f_1,d_1),\ldots,(f_m,d_m))(x)&:=\sum_{i=1}^{m}r_i\cdot f_i(x)\cdot \Big(\sum_{l=0}^{d^*-d_i}{(r\cdot x)}^l\Big) \\
        &= 
        \begin{cases}
            \sum_{i=1}^{m}r_i\cdot f_i(x)\cdot \Big(\frac{1-{(xr)}^{d^*-d_i+1}}{1-xr}\Big) & x\cdot r\neq 1\\
            \sum_{i=1}^{m}r_i\cdot f_i(x)\cdot (d^*-d_i+1) & x\cdot r= 1
        \end{cases}
    \end{align*}
Above, $r_1:=1$, $r_i:=r^{i-1+\sum_{j<i}(d^*-d_i)}$ for $i>1$.
\end{definition}

n1381.content:
\begin{definition}\label{def:deg_corr}
\lean{degreeCorrInterm,degreeCorrFinal}
\leanok
\uses{def:combine}
    Given target degree $d^*\in\mathbb{N}$, shifting parameter $r\in\mathbb{F}$, function $f:\mathcal{L}\rightarrow\mathbb{F}$, and degree $0\leq d\leq d^*$, we define $\mathsf{DegCor}(d^*,r,f,d)$ as follows.
    \[
        \mathsf{DegCor}(d^*,r,f,d)(x):=f(x)\cdot\Bigg(\sum_{i=0}^{m}{(r\cdot x)}^l\Bigg)=
        \begin{cases}
            f(x)\cdot\frac{1-{(xr)}^{d^*-d_i+1}}{1-xr} & x\cdot r\neq 1\\
            f(x)\cdot (d^*-d_i+1) & x\cdot r= 1
        \end{cases}
    \]
(Observe that $\mathsf{DegCor}(d^*,r,f,d)=\mathsf{Combine}(d^*,r,(f,d))$.)
\end{definition}

