\begin{theorem}[STIR Main Theorem]\label{thm:stir}
    Consider the following ingrediants:
    \begin{itemize}
        \item A security parameter $\lambda\in\mathbb{N}$.
        \item A Reed-Solomon code $\mathrm{RS}[\mathbb{F},\mathcal{L},d]$ with $\rho:=\frac{d}{|\mathcal{L}|}$ where $d$ is a power of $2$, and $\mathcal{L}$ is a smooth domain.
        \item A proximity parameter $\delta\in(0,1-1.05\cdot\sqrt{\rho})$.
        \item A folding parameter $k\in\mathbb{N}$ that is power of $2$ with $k\geq 4$.
    \end{itemize}
If $|\mathbb{F}|=\Omega(\frac{\lambda\cdot2^\lambda\cdot d^2\cdot{|\mathcal{L}|}^2}{\log(1/\rho)})$, there is a public-coin IOPP for $\mathrm{RS}[\mathbb{F},\mathcal{L},d]$ with the following parameters:
\begin{itemize}
    \item Round-by-round soundness error $2^{-\lambda}$.
    \item Round complexity: $M:=O(\log_k{d})$.
    \item Proof length: $|\mathcal{L}|+O_k(\log{d})$.
    \item Query complexity to the input: $\frac{\lambda}{-\log{(1-\delta)}}$.
    \item Query complexity to the proof strings: $O_k(\log{d}+\lambda\cdot\log{\Big(\frac{\log{d}}{\log{1/\rho}}\Big)})$.
\end{itemize}
\end{theorem}

