\begin{lemma}\label{lemma:rnd_by_rnd_soundness}
    Consider $(\mathbb{F},M,d,k_0,\ldots,k_M,\mathcal{L}_0,\ldots,\mathcal{L}_M,t_0,\ldots,t_M)$ and $d_0,\ldots,d_M$ as TODO, and for every $0\leq i\leq M$ let $\rho_i:=d_i/|\mathcal{L}_i|$. For every $f\notin\mathrm{RS}[\mathbb{F},\mathcal{L}_0,d_0]$ and every $\delta_0,\ldots,\delta_M$ where
    \begin{itemize}
        \item $\delta_0\in(0,\Delta(f,\mathrm{RS}[\mathbb{F},\mathcal{L}_0,d_0])]\cap(0,1-{\mathsf{B}}^*(\rho_0))$
        \item for every $0<i\leq M$: $\delta_i\in(0,\min{\{1-\rho_i-\frac{1}{|\mathcal{L}_i|},1-{\mathsf{B}^*(\rho_i)}\}})$, and
        \item for every $0<i\leq M$: $\mathrm{RS}[\mathbb{F},\mathcal{L}_i,d_i]$ is $(\delta_i,l_i)$-list decodable,
    \end{itemize}
    There exists an IOPP that has round-by-round soundness error $(\epsilon^{\mathsf{fold}},\epsilon^{\mathsf{out}}_1,\epsilon^{\mathsf{shift}}_1,\ldots,\epsilon^{\mathsf{out}}_M,\epsilon^{\mathsf{shift}}_M,\epsilon^{\mathsf{fin}})$ where:
    \begin{itemize}
        \item $\epsilon^{\mathsf{fold}}\leq\mathsf{err}^*(d_0/k_0,\rho_0,\delta_0,k_0)$.
        \item $\epsilon^{\mathsf{out}}_i\leq\frac{l^2_i}{2}\cdot{\big(\frac{d_i}{|\mathbb{F}|-|\mathcal{L}_i|}\big)}^s$
        \item $\epsilon^{\mathsf{shift}}_i\leq {(1-\delta_{i-1})}^{t_{i-1}}+\mathsf{err}^*(d_i,\rho_i,\delta_i,t_{i-1}+s)+\mathsf{err}^*(d_i/k_i,\rho_i,\delta_i,k_i)$.
        \item $\epsilon^{\mathsf{fin}}\leq{(1-\delta_M)}^{t_M}$.
    \end{itemize}
    Above, ${\mathsf{B}}^*$ and ${\mathsf{err}}^*$ are the proximity bound and error (respectively) described in Section~\ref{sec:proximity_gap}.
\end{lemma}
